shots.draw_js:
clearScene();setBig(null);setEq(null);
note("Q → Q*",400,280,"g lg");
note("策略 → 最优",880,280,"y lg");
note("这是两句话",640,400,"r lg");
setCap("Q-learning 的收敛，讲座<b>明确分成了两条</b>，而且要求不同。");

clearScene();setEq(null);
setBig("Q 对了，策略就最优","贪心读一下不就行了");
setCap("「Q 对了策略就对」在<b>读出来</b>的意义上成立 —— 但你<b>走</b>的不是那个策略。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:340,items:[
  {label:"Q → Q*",sub:"无限访问 + RM 步长",state:"on"},
  {label:"策略 → 最优",sub:"还要加 GLIE",state:"on"}]});
note("第二条多要一个条件",640,420,"y");
setCap("两条的门槛不同：<b>Q 收敛不需要 GLIE，策略最优需要</b>。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1,2],step:560,vals:[5.082,15.976,27.573],x:380,y:420,w:520,h:160,max:30,
  label:function(i){return ["ε=0.1","ε=0.3","ε=0.5"][i];},
  cls:function(i){return "r";},
  fmt:function(v){return v.toFixed(2);}});
note("Q 已经精确时的损失",640,466,"y");
setCap("哪怕 <b>Q 已经精确等于 Q*</b>，固定 ε 的策略仍然差这么多。");

clearScene();setBig(null);setEq(null);
note("学的策略",380,280,"g lg");
note("走的策略",900,280,"r lg");
note("off-policy 让两者分开",640,410,"y lg");
setCap("<b>指名反驳</b>：Q-learning 学的是贪心策略，走的是 ε-greedy。<b>两个策略。</b>");

clearScene();setBig(null);
setEq("$$\\mathbb{E}[r\\mid a_1]=\\mathbb{E}[r\\mid a_2]=0 \\;\\Longrightarrow\\; V^*=0$$","top");
note("两个动作一样好",640,300,"b lg");
note("真值就是 0",640,360,"g lg");
setCap("单状态、两动作，奖励都是<b>零均值</b>。所以 V* = 0，没有悬念。");

clearScene();setEq(null);
setBig("无偏的 max 还是无偏","每个 Q̂ 都无偏，取个最大值而已");
setCap("每个 Q̂ <b>确实</b>无偏。这个前提是对的 —— 结论不是。");

clearScene();setBig(null);
setEq("$$\\mathbb{E}\\big[\\max_a \\hat Q(a)\\big] \\;\\ge\\; \\max_a \\mathbb{E}\\big[\\hat Q(a)\\big] \\;=\\; V^*$$","top");
note("max 是凸函数",640,310,"y lg");
note("Jensen 不等式",640,370,"y lg");
setCap("<b>max 是凸函数</b>，所以 Jensen 给出「先取 max 再求期望」<b>不小于</b>反过来。");

clearScene();setBig(null);
setEq("$$\\text{20 万次模拟，}\\ \\hat Q\\ \\text{取 n 个样本的均值}$$","top");
fillBars({order:[0,1,2,3,4],step:520,vals:[0.565,0.253,0.178,0.079,0.056],
  x:330,y:430,w:620,h:170,max:0.62,
  label:function(i){return ["n=1","n=5","n=10","n=50","n=100"][i];},
  cls:function(i){return "r";},
  fmt:function(v){return v.toFixed(3);}});
note("真值是 0",640,466,"g");
setCap("实测 E[max Q̂]：n=10 时是 <b>+0.178</b>，而真值是 <b>0</b>。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1],step:800,vals:[0.001,0.178],x:380,y:430,w:520,h:170,max:0.2,
  label:function(i){return ["E[Q̂₁] 单个估计","E[max Q̂]"][i];},
  cls:function(i){return i===0?"g":"r";},
  fmt:function(v){return v.toFixed(3);}});
note("n=10，两者同时成立",640,466,"y");
setCap("同一批数据：<b>单个估计无偏（0.001），取了 max 就偏成 0.178</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:300,items:[
  {label:"每个 Q̂ 无偏",sub:"实测 0.001",state:"on"},
  {label:"E[max Q̂] 有偏",sub:"实测 +0.178",state:"dead"},
  {label:"两者不矛盾",sub:"max 不是线性操作",state:"on"}]});
note("期望只与线性操作可交换",640,420,"y");
setCap("<b>指名反驳</b>：max 不是线性的，所以期望不能穿过它。");

clearScene();setBig(null);setEq(null);
note("选动作",400,280,"b lg");
note("报它的值",880,280,"v lg");
note("同一批样本做了两件事",640,400,"r lg");
setCap("偏差的来源可以说得更准：<b>同一批样本既选了动作，又报了它的值</b>。");

clearScene();setEq(null);
setBig("两张表求个平均","多估几次取平均，方差不就小了");
setCap("平均<b>确实</b>能压方差 —— 但这里的毛病是<b>偏差</b>，平均压不掉。");

clearScene();setBig(null);
setEq("$$a^*=\\arg\\max_a Q_A(a) \\qquad \\text{report } Q_B(a^*)$$","top");
note("A 表选",420,320,"b lg");
note("B 表报",860,320,"v lg");
setCap("关键不是平均，是<b>解耦</b>：用 A 表<b>选</b>动作，用 B 表<b>报</b>它的值。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1],step:800,vals:[0.178,0.002],x:380,y:430,w:520,h:170,max:0.2,
  label:function(i){return ["单 Q（自选自报）","双 Q（A 选 B 报）"][i];},
  cls:function(i){return i===0?"r":"g";},
  fmt:function(v){return v.toFixed(3);}});
note("n=10，真值 0",640,466,"y");
setCap("同样 n=10：单 Q 偏 <b>+0.178</b>，双 Q 只剩 <b>−0.002</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:300,items:[
  {label:"平均两个有偏的",sub:"还是有偏",state:"dead"},
  {label:"解耦选与评",sub:"偏差消失",state:"on"},
  {label:"代价",sub:"两张表 · 各自数据减半",state:"on"}]});
note("关键是独立，不是数量",640,420,"y");
setCap("<b>指名反驳</b>：两张表有用不是因为平均，是因为<b>它们互相独立</b>。");
